     3	import com.loja.domain.CouponCode;
     4	import com.loja.domain.Money;
     5	import com.loja.domain.OrderItem;
     6	import com.loja.domain.Product;
     7	import org.springframework.stereotype.Component;
     8	
     9	@Component
    10	public class Buy3Pay2Coupon implements CouponStrategy {
    11	
    12	    @Override
    13	    public CouponCode getCode() {
    14	        return CouponCode.BUY3PAY2;
    15	    }
    16	
    17	    @Override
    18	    public boolean isApplicable(CouponContext context) {
    19	        return true;
    20	    }
    21	
    22	    @Override
    23	    public Money calculateDiscount(CouponContext context) {
    24	        Money totalDiscount = Money.zero();
    25	
    26	        for (OrderItem item : context.items()) {
    27	            if (item.getQuantity() >= 3) {
    28	                Product product = context.products().get(item.getSku());
    29	                int freeUnits = item.getQuantity() / 3;
    30	                Money unitDiscount = product.getPrice().multiply(freeUnits);
    31	                totalDiscount = totalDiscount.add(unitDiscount);
    32	            }
    33	        }
    34	
    35	        return totalDiscount;
    36	    }
    37	}
