306	@Service
307	public class OrderService {
308	
309	    private final OrderRepository orderRepository;
310	    private final ProductRepository productRepository;
311	    private final CustomerRepository customerRepository;
312	    private final NotificationRepository notificationRepository;
313	    private final CheckoutService checkoutService;
314	
315	    private final Map<String, PaymentProcessingResult> processedPayments = new HashMap<>();
316	
317	    public OrderService(
318	            OrderRepository orderRepository,
319	            ProductRepository productRepository,
320	            CustomerRepository customerRepository,
321	            NotificationRepository notificationRepository,
322	            CheckoutService checkoutService) {
323	        this.orderRepository = orderRepository;
324	        this.productRepository = productRepository;
325	        this.customerRepository = customerRepository;
326	        this.notificationRepository = notificationRepository;
327	        this.checkoutService = checkoutService;
328	    }
329	
330	    @Transactional
331	    public Order createOrder(OrderRequest request) {
332	        OrderSummary summary = checkoutService.calculateSummary(request);
333	
334	        List<OrderItem> items = request.items().stream()
335	            .map(i -> new OrderItem(i.sku(), i.quantity()))
336	            .toList();
337	
338	        Order order = new Order(request.customer().cpf(), items, summary);
339	
340	        customerRepository.findById(request.customer().cpf())
341	            .orElseGet(() -> customerRepository.save(new Customer(request.customer().cpf())));
342	
343	        return orderRepository.save(order);
344	    }
345	
346	    @Transactional
347	    public Order processPayment(Long orderId, PaymentRequest request) {
348	        if (request.transactionId() == null || request.paidAt() == null) {
349	            throw ErrorCode.INVALID_ORDER.asException();
350	        }
351	
352	        Order order = orderRepository.findById(orderId)
353	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
354	
355	        String paymentKey = orderId + ":" + request.transactionId();
356	
357	        synchronized (processedPayments) {
358	            if (processedPayments.containsKey(paymentKey)) {
359	                PaymentProcessingResult cached = processedPayments.get(paymentKey);
360	                if (cached.success()) {
361	                    return orderRepository.findById(orderId).orElseThrow();
362	                } else {
363	                    throw cached.error().asException();
364	                }
365	            }
366	        }
367	
368	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
369	            if (order.getPaymentTransactionId() != null &&
370	                order.getPaymentTransactionId().equals(request.transactionId())) {
371	                synchronized (processedPayments) {
372	                    processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
373	                }
374	                return order;
375	            }
376	            synchronized (processedPayments) {
377	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.OPERATION_NOT_ALLOWED));
378	            }
379	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
380	        }
381	
382	        Duration elapsed = Duration.between(order.getCreatedAt(), request.paidAt());
383	        if (elapsed.toHours() > 48) {
384	            order.cancel();
385	            orderRepository.save(order);
386	            notificationRepository.save(new Notification(
387	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
388	            ));
389	            synchronized (processedPayments) {
390	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.ORDER_EXPIRED));
391	            }
392	            throw ErrorCode.ORDER_EXPIRED.asException();
393	        }
394	
395	        try {
396	            decreaseStock(order);
397	        } catch (IllegalStateException e) {
398	            order.cancel();
399	            orderRepository.save(order);
400	            notificationRepository.save(new Notification(
401	                order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
402	            ));
403	            synchronized (processedPayments) {
404	                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.INSUFFICIENT_STOCK));
405	            }
406	            throw ErrorCode.INSUFFICIENT_STOCK.asException();
407	        }
408	
409	        order.markAsPaid(request.transactionId());
410	        orderRepository.save(order);
411	
412	        Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
413	            .orElseThrow(() -> ErrorCode.CUSTOMER_NOT_FOUND.asException());
414	        customer.addCredit(order.getSummary().nextPurchaseCredit());
415	        customerRepository.save(customer);
416	
417	        notificationRepository.save(new Notification(
418	            order.getCustomerCpf(), NotificationType.PAYMENT_APPROVED, orderId
419	        ));
420	
421	        synchronized (processedPayments) {
422	            processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
423	        }
424	
425	        return order;
426	    }
427	
428	    @Transactional
429	    public Order shipOrder(Long orderId, String trackingCode) {
430	        if (trackingCode == null || trackingCode.isBlank()) {
431	            throw ErrorCode.INVALID_ORDER.asException();
432	        }
433	
434	        Order order = orderRepository.findById(orderId)
435	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
436	
437	        if (order.getStatus() != OrderStatus.PAID) {
438	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
439	        }
440	
441	        order.ship(trackingCode);
442	        orderRepository.save(order);
443	
444	        notificationRepository.save(new Notification(
445	            order.getCustomerCpf(), NotificationType.ORDER_SHIPPED, orderId
446	        ));
447	
448	        return order;
449	    }
450	
451	    @Transactional
452	    public Order deliverOrder(Long orderId) {
453	        Order order = orderRepository.findById(orderId)
454	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
455	
456	        if (order.getStatus() != OrderStatus.SHIPPED) {
457	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
458	        }
459	
460	        order.deliver();
461	        return orderRepository.save(order);
462	    }
463	
464	    @Transactional
465	    public Order cancelOrder(Long orderId) {
466	        Order order = orderRepository.findById(orderId)
467	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
468	
469	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
470	            throw ErrorCode.OPERATION_NOT_ALLOWED.asException();
471	        }
472	
473	        boolean wasPaid = order.isPaid();
474	
475	        order.cancel();
476	        orderRepository.save(order);
477	
478	        if (wasPaid) {
479	            increaseStock(order);
480	
481	            Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf())
482	                .orElseThrow(() -> ErrorCode.CUSTOMER_NOT_FOUND.asException());
483	            customer.removeCredit(order.getSummary().nextPurchaseCredit());
484	            customerRepository.save(customer);
485	        }
486	
487	        notificationRepository.save(new Notification(
488	            order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId
489	        ));
490	
491	        return order;
492	    }
493	
494	    @Transactional(readOnly = true)
495	    public Order getOrder(Long orderId) {
496	        return orderRepository.findById(orderId)
497	            .orElseThrow(() -> ErrorCode.ORDER_NOT_FOUND.asException());
498	    }
499	
500	    private void decreaseStock(Order order) {
501	        for (OrderItem item : order.getItems()) {
502	            Product product = productRepository.findBySkuForUpdate(item.getSku())
503	                .orElseThrow(() -> ErrorCode.UNKNOWN_PRODUCT.asException());
504	            product.decreaseStock(item.getQuantity());
505	            productRepository.save(product);
506	        }
507	    }
508	
509	    private void increaseStock(Order order) {
510	        for (OrderItem item : order.getItems()) {
511	            Product product = productRepository.findBySkuForUpdate(item.getSku())
512	                .orElseThrow(() -> ErrorCode.UNKNOWN_PRODUCT.asException());
513	            product.increaseStock(item.getQuantity());
514	            productRepository.save(product);
515	        }
516	    }
517	
518	    private record PaymentProcessingResult(boolean success, ErrorCode error) {}
519	}
