545	            case MIDWEST -> new InsuranceRate(BigDecimal.valueOf(1.5), null);
546	            case NORTH -> new InsuranceRate(BigDecimal.valueOf(2.5), new Money("30.00"));
547	            case NORTHEAST -> new InsuranceRate(BigDecimal.valueOf(2.0), new Money("30.00"));
548	        };
549	    }
