530	    public Money calculateInsurance(Money productsSubtotal, Region region) {
531	        InsuranceRate rate = getRate(region);
532	        Money insurance = productsSubtotal.percentage(rate.percentage());
533	
534	        if (rate.maxAmount() != null && insurance.isGreaterThan(rate.maxAmount())) {
535	            return rate.maxAmount();
536	        }
537	
538	        return insurance;
539	    }
540	
541	    private InsuranceRate getRate(Region region) {
542	        return switch (region) {
543	            case SOUTHEAST -> new InsuranceRate(BigDecimal.valueOf(1.0), null);
544	            case SOUTH -> new InsuranceRate(BigDecimal.valueOf(1.0), null);
545	            case MIDWEST -> new InsuranceRate(BigDecimal.valueOf(1.5), null);
546	            case NORTH -> new InsuranceRate(BigDecimal.valueOf(2.5), new Money("30.00"));
547	            case NORTHEAST -> new InsuranceRate(BigDecimal.valueOf(2.0), new Money("30.00"));
548	        };
549	    }
550	
551	    private record InsuranceRate(BigDecimal percentage, Money maxAmount) {}
552	}

