  3	import org.springframework.beans.factory.annotation.Value;
  4	import org.springframework.stereotype.Component;
  5	import org.springframework.web.client.RestClient;
  6	
  7	import java.time.Duration;
  8	
  9	@Component
 10	public class TransLogClient {
 11	
 12	    private final String baseUrl;
 13	    private final RestClient restClient;
 14	
 15	    public TransLogClient(@Value("${translog.url}") String baseUrl,
 16	                          @Value("${translog.timeout}") int timeoutMs) {
 17	        this.baseUrl = baseUrl;
 18	        this.restClient = RestClient.builder()
 19	            .baseUrl(baseUrl)
 20	            .build();
 21	    }
 22	
 23	    public QuoteResult getQuote(String zipCode, int weightGrams, String service) {
 24	        try {
 25	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
 26	                baseUrl, zipCode, weightGrams, service);
 27	
 28	            QuoteResponse response = restClient.get()
 29	                .uri(url)
 30	                .retrieve()
 31	                .body(QuoteResponse.class);
 32	
 33	            if (response == null || response.error != null) {
 34	                return null;
 35	            }
 36	
 37	            return new QuoteResult(response.priceCents, response.etaHours);
 38	        } catch (Exception e) {
 39	            throw new TransLogUnavailableException("TransLog is unavailable", e);
 40	        }
 41	    }
 42	
 43	    private static class QuoteResponse {
 44	        public Integer priceCents;
 45	        public Integer etaHours;
 46	        public String error;
 47	    }
 48	
 49	    public record QuoteResult(Integer priceCents, Integer etaHours) {}
 50	}
